import{_ as e,c as l,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"水風井","description":"周易折中 - 水風井","frontmatter":{"title":"水風井","description":"周易折中 - 水風井"},"headers":[],"relativePath":"classics/zhezhong/054.md","filePath":"classics/zhezhong/054.md"}'),h={name:"classics/zhezhong/054.md"};function n(p,a,d,t,s,o){return r(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="水風井" tabindex="-1">水風井 <a class="header-anchor" href="#水風井" aria-label="Permalink to “水風井”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>〈井序〉：“卦困乎上者必反下，故受之以井。承上升而不已必困為言，謂上井不已而困，則必反於下也。物之在下者莫如井，井所以次困也。為卦坎上巽下，坎水也，巽之象則木也，巽之義則入也。木器之象，木入於水下而上乎水，汲井之象也。”</p><p>井：改邑不改井，無喪無得，往來井井，汔至亦未繘井，羸其瓶兇</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>井者，穴地出水之處。以巽木入乎坎水之下，而上出其水，故為井。改邑不改井，故無喪無得，而往者來者皆井其井也。汔，幾也；繘，綆也；羸，敗也。汲井幾至，未盡綆而敗其瓶，則兇也。其佔為事仍舊無得喪，而又當敬勉，不可幾成而敗也。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>井之為物，常而不可改也。邑可改而之他，井不可遷也，故曰“改邑不改井”。汲之而不竭，存之而不盈，無喪無得也。至者皆得其用，往來井井也。無喪無得，其徳也常。往來井井，其用也周常也，周也，井之道也。汔，幾也；繘，綆也。井以濟用為功，幾至而未及用，亦與未下繘於井同也。君子之道貴乎有成，所以五穀不熟不如荑稗，掘井九仞而不及泉猶為棄井。有濟物之用而未及物，猶無有也。羸敗其瓶而失之，其用喪矣，是以兇也。羸，毀敗也。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>鄭氏康成曰 ：井以汲水，水無空竭，猶人君以政教養天下，惠澤無窮也。</p></li><li><p>丘氏富國曰 ：改邑不改井，井之體也；無喪無得，井之徳也。“往來井井，井井之用也”此三句言井之事；“汔至亦未繘井，未及於用也；羸其瓶，失其用也”此二句言汲井之事。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>改邑不改井，句解說多錯文意，蓋言所在之邑，其井皆無異制，如諸葛孔明行軍之處，千井齊甃者，以喻王道之行，國不異政，家不殊俗也。無喪無得，則言井無盈涸，以喻道之可久。往來井井，則言所及者多，以喻道之可大。此三句皆言井在人事，則王者養民之政是也。然井能澤物而汲之者器，政能養民而行之者人。無器則水之功不能上行，無人則王者之澤不能下究。故“汔至”以下，又以汲井之事言之。</p><p>象曰：木上有水，井；君子以勞民勸相</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>木上有水，津潤上行，井之象也。勞民者，以君養民；勸相者，使民相養，皆取井養之義。</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>木承水而上之，乃器汲水而出，井之象。君子觀井之象，法井之德，以勞徠其民而勸勉以相助之道也。勞徠其民，法井之用也；勸民使相助，法井之施也。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>張子曰 ：養而不窮，莫若勞民而勸相也。</p></li><li><p>楊氏繪曰 ：水性潤下，能上潤於物者，井之用也。</p></li><li><p>朱子語類雲 ：木上有水，井。說者以為木是汲器，則後面卻有瓶。瓶自是瓦器，只是說水之津潤上行至那木之杪，這便是井水上行之象。 又云：草木之生津潤皆上行，直至樹末，便是木上有水之義。如菖蒲葉每晨葉尾皆有水如珠顆，雖藏之密室亦然，非露水也。問如此則井之義與木上有水何預？曰：木上有水，便如水本在井底，卻能汲上來給人之食，故取象如此。</p></li><li><p>又云：草木之生津潤皆上行，直至樹末，便是木上有水之義。如菖蒲葉每晨葉尾皆有水如珠顆，雖藏之密室亦然，非露水也。問如此則井之義與木上有水何預？曰：木上有水，便如水本在井底，卻能汲上來給人之食，故取象如此。</p></li><li><p>李氏心傳曰 ：勸相即相友相助相扶持之意。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>大象“木上有水”，須以朱子之說為長。《彖傳》“巽乎水而上水”，則鄭氏桔槔之說不妨並存也。勞民者如巽風之布號令，勸相者如坎水之相灌輸。</p><p>彖曰：巽乎水而上水，井井養而不窮也</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>以卦象釋卦名義。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>鄭氏康成曰 ：坎水也，巽木，桔槔也。桔槔引瓶下入泉口，汲水而出，井之象也。</p></li><li><p>荀氏爽曰 ：木入水出，井之象也。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>釋名之下又著“井養而不窮也”一句，亦以起釋辭之意。</p><p>改邑不改井，乃以剛中也；汔至，亦未繘井，未有功也；羸其瓶，是以兇也</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>以卦體釋卦辭。“無喪無得，往來井井”兩句意與“不改井”同，故不復出。剛中以二五而言。未有功而敗其瓶，所以兇也。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>巽入於水，下而上其水者，井也。井之養於物，不有窮已，取之而不竭，德有常也。邑可改，井不可遷，亦其德之常也。二五之爻，剛中之德，其常乃如是。卦之才與義合也。雖使幾至既未為用，亦與未繘井同。井以濟用為功，水出乃為用，未出則何功也？瓶所以上水而致用也，羸敗其瓶，則不為用矣，是以兇也。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>蘇氏軾曰 ：井井未嘗有得喪，繘井之為功，羸瓶之為兇，在汲者爾。</p></li><li><p>晁氏說之曰 ：或謂彖主三陽言，五“寒泉食”，是陽剛居中，邑可改而井不可改也；三“井渫不食”，是未有功也；二“甕敝漏”，是羸其瓶而兇者也。</p></li><li><p>郭氏雍曰 ：不言“無喪無得，往來井井”者，蓋皆系乎剛中之德。聖人舉一以明之耳。</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>井惟有常，故其體則無喪無得，其用則往來井井。王道惟有常，故其體則久而無弊，其用則廣而及物。故言“改邑不改井”，足以包下二者。</p><p>/books/106/48/1.html</p><p>初六 井泥不食，舊井無禽</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>井以陽剛為泉，上出為功。初六以陰居下，故為此象。蓋井不泉而泥，則人所不食，而禽鳥亦莫之顧矣。</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>井與鼎皆物也，就物以為義。六以陰柔居下，上無應援，無上水之象，不能濟物，乃井之不可食也。井之不可食以泥汙也，在井之下有泥之象。井之用以其水之養人也，無水則舍置不用矣。井水之上，人獲其用，禽鳥亦就而求焉。舊廢之井，人既不食水，不復上，則禽鳥亦不復往矣。蓋無以濟物也。井本濟人之物，六以陰居下，無上水之象，故為不食。井之不食以泥也，猶人當濟物之時而才弱無援，不能及物，為時所舍也。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏弼曰 ：最在井底，上又無應，沈滯滓穢，故曰“井泥不食”也。井泥而不可食，則是久井不見渫治者也。久井不見渫治，禽所不向，而況人乎？</p></li><li><p>蔡氏清曰 ：井以陽剛為泉，而初六則陰柔也，故為井泥、為舊井。井以上出為功，而初六則居下，故為不食、為無禽。</p></li></ul><p>象曰：井泥不食，下也；舊井無禽，時舍也</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>言為時所棄。</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>以陰而居井之下，泥之象也。無水而泥，人所不食也。人不食則水不上，無以及禽鳥，禽鳥亦不至矣。見其不能濟物，為時所舍置不用也。若能及禽鳥，是亦有所濟也。舍上聲，與幹之時舍音不同。</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><p>孔氏穎逹曰 ：下也者，以其最在井下，故為井泥也。時舍也者，人既不食，禽亦不向，是一時共棄捨也。</p><p>九二：井谷射鮒，甕敝漏</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>九二剛中有泉之象，然上無正應，下比初六，功不上行，故其象如此。</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>二雖剛陽之才，而居下上無應，而比於初，不上而下之象也。井之道上行者也，㵎谷之水則旁出而就下。二居井而就下，失井之道，乃井而如谷也。井上出則養人而濟物，今乃下就汙泥注於鮒而已。鮒或以為蝦，或以為蟆，井泥中微物耳。射，注也，如谷之下流注於鮒也。甕敝漏，如甕之破漏也。陽剛之才本可以養人濟物，而上無應援，故不能上而就下，是以無濟用之功。如水之在甕，本可為用，乃破敝而漏之，不為用也。井之初二無功而不言悔咎，何也？曰：失則有悔，過則為咎。無應援而不能成用，非悔咎乎？居二比初，豈非過乎？曰：處中非過也，不能上由無援，非以比初也。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li>張氏振淵曰 ：以井言，則為井谷之泉，僅下注於鮒；以汲井言，則為敝壊之甕，水反漏於下也。</li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>井谷者，井中出水之穴竅也。井能出水則非泥井也，而其功僅足以射鮒者，上無汲引之人，如瓶甕之敝漏然，則不能自濟於人用也，決矣。在卦則以井喻政，以汲之者喻行政之人；在爻則下體以井喻材徳之士，汲之者喻進用之君；上體以井喻徳位之君，汲之者喻被澤之眾。三義相因而取喻不同。</p><p>象曰：井谷射鮒，無與也</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>井以上出為功，二陽剛之才本可濟用，以在下而上無應援，是以下比而射鮒。若上有與之者，則當汲引而上，成井之功矣。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><p>谷氏家傑曰 ：謂有泉而無與者與無泉而時棄者，自不可同也。</p><p>九三：井渫不食，為我心惻，可用汲，王明並受其福</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>渫，不停汙也。井渫不食，而使人心惻，可用汲矣。王明則汲井以及物，而施者受者並受其福也。九三以陽居陽，在下之上而未為時用，故其象佔如此。</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>三以陽剛居得其正，是有濟用之才者也。在井下之上，水之清潔可食者也。井以上為用，居下未得其用也。陽之性上，又志應上六，處剛而過中，汲汲於上進，乃有才用而切於施為。未得其用，則如井之渫治清潔而不見食，為心之惻怛也。三居井之時，剛而不中，故切於施為，異乎用之則行，舍之則藏者也。然明王用人豈求備也？故王明則受福矣。三之才足以濟用，如井之清潔可用汲而食也。若上有明王，則當用之而得其效，賢才見用則已得行其道，君得享其功，下得被其澤，上下並受其福也。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li>蔡氏清曰 ：為我心惻，我指旁人，所謂行惻也，非謂九三自惻。也可用汲、帶連王明並受其福，皆惻之之辭也。</li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>不曰明王而曰王明，乃惻者祈禱之辭，言王若明，則吾儕並受其福矣。</p><p>象曰：井渫不食，行惻也；求王明，受福也</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>行惻者，行道之人皆以為惻。</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>井渫治而不見食，乃人有才知而不見用，以不得行為憂惻也。既以不得行為惻，則豈免有求也？故求王明而受福，志切於行也。</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>趙氏汝梅曰 ：井不以不食為憂，賢者不以不遇而惻。心惻者，行人也，行汲之人為之求王者之明也。求王之明，豈朋比以幹祿？為其見知於上，則福被生民，猶井汲而出，然後利及於人也。</p></li><li><p>王氏申子曰 ：井渫而不為人所食，縱不自惻，行道之人亦為之惻然矣。縱不求人之我用，人亦為之求之，以並受其福矣。</p></li></ul><p>六四：井甃無咎</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>以六居四，雖得其正，然陰柔不泉，則但能脩治而無及物之功，故其象為井甃，而佔則無咎。佔者能自脩治，則雖無及物之功，而亦可以無咎矣。</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>四雖陰柔而處正，上承九五之君，才不足以廣施利物，亦可自守者也。故能脩治則得無咎。甃，砌累也，謂脩治也。四雖才弱不能廣濟物之功，脩治其事不至於廢可也。若不能脩治，廢其養人之功，則失井之道，其咎大矣。居高位而得剛陽中正之君，但能處正承上不廢其事，亦可以免咎也。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>丘氏富國曰 ：三在內卦，渫井內以致其潔；四在外卦，甃井外以御其汙。蓋不渫則汙者不潔，不甃則潔者易汙。</p></li><li><p>來氏知徳曰 ：六四陰柔得正，近九五之君，蓋脩治其井以瀦蓄九五之寒泉者也。佔者能脩治臣下之職，則可以因君而成井養之功，斯無咎矣。</p></li></ul><p>象曰：井甃無咎，脩井也</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>甃者，脩治於井也。雖不能大其濟物之功，亦能脩治不廢也，故無咎。僅能免咎而已，若在剛陽，自不至如是，如是則可咎矣。</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>虞氏翻曰 ：脩治也，以瓦甓壘井稱甃。</p></li><li><p>蘇氏軾曰 ：脩潔也。陽為動為實，陰為靜為虛。泉者，所以為井也，動也，實也。井者，泉之所寄也，靜也，虛也。初六最下，故曰泥；上六最上，故曰收；六四居其閒而不失正，故曰甃。甃之於井，所以御惡而潔井也。井待是而潔，故無咎。</p></li></ul><p>九五：井洌寒泉，食</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>洌，潔也。陽剛中正，功及於物，故為此象。佔者有其徳，則契其象也。</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>五以陽剛中正居尊位，其才其徳盡善盡羙。井洌寒泉，食也。洌謂甘潔也，井泉以寒為羙，甘潔之寒泉可為人食也。於井道為至善也。然而不言吉者，井以上出為成功，未至於上，未及用也，故至上而後言元吉。</p><h3 id="集說-12" tabindex="-1">集說 <a class="header-anchor" href="#集說-12" aria-label="Permalink to “集說”">​</a></h3><ul><li>易氏祓曰 ：三與五皆泉之潔者。三居甃下，未汲之泉也，故曰“不食”。五出乎甃，已汲之泉也，故言“食”。</li></ul><p>象曰：寒泉之食，中正也</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>寒泉而可食，井道之至善者也。九五中正之德，為至善之義。</p><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>詩云：“泉之竭矣，不雲自中。”蓋不中，則源不常裕而不寒也。又云：“冽彼下泉，浸彼苞蕭。”蓋不正，則流不逮下而不食也。</p><p>上六：井收勿幕，有孚，元吉</p><h3 id="本義-11" tabindex="-1">本義 <a class="header-anchor" href="#本義-11" aria-label="Permalink to “本義”">​</a></h3><p>收，汲取也（晁氏雲：收，鹿盧收繘者也，亦通）。幕，蔽覆也。有孚，謂其出有源而不窮也。井以上出為功，而坎口不揜，故上六雖非陽剛，而其象如此。然佔者應之，必有孚，乃元吉也。</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>井以上出為用，居井之上，井道之成也。收，汲取也；幕，蔽覆也。取而不蔽，其利無窮。井之施廣矣大矣，有孚有常而不變也，博施而有常，大善之吉也。夫體井之用，博施而有常，非大人孰能？它卦之終為極、為變，唯井與鼎終乃為成功，是以吉也。</p><h3 id="案-7" tabindex="-1">案 <a class="header-anchor" href="#案-7" aria-label="Permalink to “案”">​</a></h3><p>勿幕，謂取之無禁，所謂“往來井井”者也。有孚，謂有源不窮，所謂“無喪無得”者也。此爻得備卦之義者，巽乎水而上，水至此爻則上之極也。</p><p>象曰：元吉在上，大成也</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>以大善之吉在卦之上，井道之大成也。井以上為成功。</p><p>總論</p><ul><li><p>李氏過曰 ：初井泥，二井谷，皆廢井也；三井渫則渫初之泥；四井甃則甃二之谷。既渫且甃，井道全矣。故五井洌而泉寒，上井收而勿幕，功始及物而井道大成矣。</p></li><li><p>丘氏富國曰 ：先儒以三陽為泉，三陰為井，陽實陰虗之象也。九二言井谷射鮒，九三言井渫不食，九五言井洌寒泉，曰射、曰渫、曰洌，非泉之象乎？初六言井泥不食，六四言井甃無咎，上六言井收勿幕，曰泥、曰甃、曰收，非井之象乎？以卦序而言，則二之射始逹之泉也，三之渫已潔之泉也，五之洌則可食之泉矣。初之泥方掘之井也，四之甃已修之井也，上之收則已汲之井矣。又以二爻為一例，則初二皆在井下不見於用，故初為泥而二為谷；三四皆在井中將見於用，故三為渫而四為甃；五上皆在井上而已見於用矣，故五言食而上言收也。</p></li></ul>',118)])])}const m=e(h,[["render",n]]);export{b as __pageData,m as default};
